// World Tour — Geo, route: jsx
// Source: world-tour
//
// Self-contained: every local import is inlined below. Requires only d3, geojson, react, topojson-client, topojson-specification, us-atlas, versor, world-atlas.
// versor ships no types — keep untyped-modules.d.ts beside this file.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

/// <reference path="./untyped-modules.d.ts" />

import { feature, mesh } from 'topojson-client';
import countries110m from 'world-atlas/countries-110m.json';
import statesUs from 'us-atlas/states-10m.json';
import type { GeometryCollection, Topology } from 'topojson-specification';
import type { Feature, FeatureCollection, Geometry, MultiLineString, LineString } from 'geojson';
import { useEffect, useMemo, useState } from 'react';
import * as d3 from 'd3';
import versor from 'versor';

// ---- inlined from geo ----
// The atlases ship untyped JSON. One cast per topology at this boundary keeps every
// consumer strict, and converting here means each chart does not re-derive the same
// geometry at module load.

type Named = { name: string };
type NamedFeature = Feature<Geometry, Named>;

const world = countries110m as unknown as Topology<{
  countries: GeometryCollection<Named>;
  land: GeometryCollection;
}>;

const us = statesUs as unknown as Topology<{
  states: GeometryCollection<Named>;
  nation: GeometryCollection;
}>;

const worldCountries = feature(
  world,
  world.objects.countries
) as FeatureCollection<Geometry, Named>;

const worldLand = feature(world, world.objects.land) as FeatureCollection<Geometry>;

/** Shared borders only, so neighbouring outlines are stroked once instead of twice. */
const worldBorders = mesh(
  world,
  world.objects.countries,
  (a, b) => a !== b
) as MultiLineString;

const usNation = feature(us, us.objects.nation) as FeatureCollection<Geometry>;

const usStateBorders = mesh(
  us,
  us.objects.states,
  (a, b) => a !== b
) as MultiLineString;

/**
 * The 50 states plus DC. geoAlbersUsa cannot project FIPS ids of 60 and above
 * (territories) and returns null for them, which becomes a NaN centroid downstream.
 * Use this rather than the raw collection for anything Albers-projected.
 */
const usStates: NamedFeature[] = (
  feature(us, us.objects.states) as FeatureCollection<Geometry, Named>
).features.filter((d) => Number(d.id) < 60);

const usStatesCollection: FeatureCollection<Geometry, Named> = {
  type: 'FeatureCollection',
  features: usStates
};

/**
 * FNV-1a over an id, run through the murmur3 finalizer. Two-character FIPS ids barely
 * differ, and without the finalizer they map to a near-constant. Returns [0, 1).
 * Charts use it to synthesize per-region values deterministically instead of fetching.
 */
function hashUnit(id: string, salt = 0): number {
  let h = 2166136261 ^ salt;
  for (let i = 0; i < id.length; i++) {
    h = Math.imul(h ^ id.charCodeAt(i), 16777619);
  }
  h ^= h >>> 16;
  h = Math.imul(h, 2246822507);
  h ^= h >>> 13;
  return (h >>> 0) / 4294967296;
}

const MARGIN = 10;
const MAX_HEIGHT = 560;
/** Vertical band above the globe reserved for the country name. */
const LABEL_BAND = 26;
/** One leg is a dwell on the current country followed by the flight to the next. */
const LEG_MS = 2600;
const DWELL_FRAC = 0.3;
/** Fraction of the flight spent growing the arc; the remainder retracts it from behind. */
const GROW_FRAC = 0.62;
/** Degrees of northward tilt, so the visited country sits just above the globe's centre. */
const TILT = 20;

const TOUR = [
  'United States of America',
  'Brazil',
  'South Africa',
  'Egypt',
  'India',
  'China',
  'Japan',
  'Australia',
  'Russia',
  'France'
];

const sphere: d3.GeoSphere = { type: 'Sphere' };

type Stop = {
  name: string;
  feature: NamedFeature;
  center: [number, number];
  rotation: [number, number, number];
};

function planStops(tour: Data): Stop[] {
  return tour.map((name) => {
    const feature = worldCountries.features.find((d) => d.properties.name === name);
    if (!feature) throw new Error(`world-atlas has no country named ${name}`);
    const center = d3.geoCentroid(feature);
    return { name, feature, center, rotation: [-center[0], TILT - center[1], 0] };
  });
}

/** Countries to visit in order; each name must match a world-atlas country. */
export type Data = string[];

export default function WorldTour({ data = TOUR, width }: { data?: Data; width: number }) {
  const height = Math.min(Math.round(width * 0.78), MAX_HEIGHT);
  const [elapsed, setElapsed] = useState(0);

  const stops = useMemo(() => planStops(data), [data]);

  useEffect(() => {
    const timer = d3.timer((ms) => setElapsed(ms));
    return () => timer.stop();
  }, []);

  const fit = useMemo(() => {
    const globeHeight = Math.max(height - LABEL_BAND - MARGIN, 0);
    const projection = d3
      .geoOrthographic()
      .fitSize([Math.max(width - MARGIN * 2, 0), globeHeight], sphere);
    return {
      scale: projection.scale(),
      translate: [width / 2, LABEL_BAND + globeHeight / 2] as [number, number]
    };
  }, [width, height]);

  const frame = useMemo(() => {
    const cycle = (elapsed % (stops.length * LEG_MS)) / LEG_MS;
    const leg = Math.floor(cycle);
    const u = cycle - leg;
    const from = stops[leg];
    const to = stops[(leg + 1) % stops.length];

    // Below DWELL_FRAC the globe is parked on `from`, which is also what the first
    // paint shows before the timer has ticked at all.
    const flying = u > DWELL_FRAC;
    const t = flying ? d3.easeCubicInOut((u - DWELL_FRAC) / (1 - DWELL_FRAC)) : 0;

    // Slerp between the two orientations rather than lerping the Euler angles, which
    // would swing the wrong way round the globe whenever a leg crosses the antimeridian.
    const rotation = flying ? versor.interpolate(from.rotation, to.rotation)(t) : from.rotation;
    const projection = d3
      .geoOrthographic()
      .precision(0.2)
      .scale(fit.scale)
      .translate(fit.translate)
      .rotate(rotation);
    const path = d3.geoPath(projection);

    const along = d3.geoInterpolate(from.center, to.center);
    const arc: LineString | null = flying
      ? {
          type: 'LineString',
          coordinates:
            t < GROW_FRAC
              ? [from.center, along(t / GROW_FRAC)]
              : [along((t - GROW_FRAC) / (1 - GROW_FRAC)), to.center]
        }
      : null;

    const active = flying ? to : from;
    return {
      name: active.name,
      sphere: path(sphere) ?? undefined,
      land: path(worldLand) ?? undefined,
      borders: path(worldBorders) ?? undefined,
      country: path(active.feature) ?? undefined,
      arc: arc ? (path(arc) ?? undefined) : undefined
    };
  }, [elapsed, fit, stops]);

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Animated orthographic globe touring ten countries, rotating between them along great circle arcs"
    >
      <text
        x={width / 2}
        y={LABEL_BAND - 9}
        textAnchor="middle"
        fill="var(--text)"
        fontSize={14}
      >
        {frame.name}
      </text>
      <path d={frame.sphere} fill="var(--panel)" stroke="var(--muted)" strokeWidth={1.5} />
      <path d={frame.land} fill="var(--muted)" fillOpacity={0.45} />
      <path
        d={frame.country}
        fill="var(--accent)"
        stroke="var(--accent)"
        strokeWidth={0.5}
        strokeLinejoin="round"
      />
      <path
        d={frame.borders}
        fill="none"
        stroke="var(--bg)"
        strokeWidth={0.5}
        strokeLinejoin="round"
      />
      {frame.arc && <path d={frame.arc} fill="none" stroke="var(--text)" strokeWidth={1.5} />}
    </svg>
  );
}
